          "size": {
            "type": "integer",
            "description": "The size of the square compartment"
          },
          "location": {
            "type": "string",
            "description": "The location of the square compartment"
          }
        },
        "required": ["type", "size", "location"]
      }
    }
  },
  "required": ["name", "compartment"]
}
```
